```typescript
/** Debounce: tunda eksekusi function sampai user berhenti memicu selama N ms. */
function debounce<T extends (...args: any[]) => void>(
    fn: T,
    delay: number
): (...args: Parameters<T>) => void {
    let timeoutId: ReturnType<typeof setTimeout> | null = null;

    return function (this: any, ...args: Parameters<T>) {
        // Clear timer sebelumnya kalau ada
        if (timeoutId !== null) {
            clearTimeout(timeoutId);
        }
        // Set timer baru
        timeoutId = setTimeout(() => {
            fn.apply(this, args);
            timeoutId = null;
        }, delay);
    };
}

// Versi dengan leading edge (langsung eksekusi pertama kali)
function debounceLeading<T extends (...args: any[]) => void>(
    fn: T,
    delay: number
): (...args: Parameters<T>) => void {
    let timeoutId: ReturnType<typeof setTimeout> | null = null;
    let isFirstCall = true;

    return function (this: any, ...args: Parameters<T>) {
        if (isFirstCall) {
            fn.apply(this, args);
            isFirstCall = false;
            return;
        }
        if (timeoutId !== null) clearTimeout(timeoutId);
        timeoutId = setTimeout(() => {
            fn.apply(this, args);
            isFirstCall = true;
            timeoutId = null;
        }, delay);
    };
}

// Contoh: search input
const searchInput = document.getElementById('search') as HTMLInputElement;
const handleSearch = debounce((value: string) => {
    console.log('Searching for:', value);
    fetch(`/api/search?q=${value}`);
}, 300);

searchInput.addEventListener('input', (e) => {
    handleSearch((e.target as HTMLInputElement).value);
});
